-- Disposable G5 integration fixture ONLY, extending the existing US03 test
-- tables with the legacy columns exercised by the canonical booking writer.
-- No production migration, data, external push configuration or payment.
ALTER TABLE public.bookings ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE public.bookings ADD COLUMN salon_slug text, ADD COLUMN request_id text UNIQUE,
 ADD COLUMN calendar_slot_id integer UNIQUE, ADD COLUMN client_id integer,
 ADD COLUMN service_id integer, ADD COLUMN price_snapshot integer, ADD COLUMN currency_code text;
CREATE TABLE public.cities(id bigint PRIMARY KEY,slug text,timezone text);
CREATE TABLE public.market_capabilities(market_id bigint,capability_code text,enabled boolean,config_json jsonb);
CREATE TABLE public.market_provider_bindings(market_id bigint,provider_type text,provider_code text,enabled boolean,priority integer,profile_code text,config_json jsonb);
CREATE TABLE public.api_idempotency_keys(idempotency_key text PRIMARY KEY,endpoint text NOT NULL,request_hash text NOT NULL,response_code integer,response_body jsonb);
CREATE TABLE public.clients(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,salon_id integer NOT NULL REFERENCES public.salons(id),name text NOT NULL,phone text NOT NULL,UNIQUE(salon_id,phone));
CREATE TABLE public.calendar_slots(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,master_id integer NOT NULL REFERENCES public.masters(id),salon_id integer NOT NULL REFERENCES public.salons(id),start_at timestamptz NOT NULL,end_at timestamptz NOT NULL,status text NOT NULL,request_id text UNIQUE,CHECK(start_at<end_at),UNIQUE(master_id,start_at,end_at));
ALTER TABLE public.bookings ADD FOREIGN KEY(calendar_slot_id) REFERENCES public.calendar_slots(id),ADD FOREIGN KEY(client_id) REFERENCES public.clients(id);
CREATE TABLE public.client_access_tokens(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,client_id integer NOT NULL REFERENCES public.clients(id),booking_id integer NOT NULL REFERENCES public.bookings(id),token_hash text NOT NULL UNIQUE,token_last4 text NOT NULL,purpose text NOT NULL,revoked_at timestamptz);
CREATE TABLE public.client_sources(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,client_id integer NOT NULL REFERENCES public.clients(id),booking_id integer NOT NULL REFERENCES public.bookings(id),source_type text,source_slug text);
CREATE TABLE public.client_audit_events(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,client_id integer NOT NULL REFERENCES public.clients(id),booking_id integer NOT NULL REFERENCES public.bookings(id),actor_type text,action text,metadata jsonb);
CREATE TABLE public.app_notifications(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,notification_uid text NOT NULL UNIQUE,target_type text,target_id text,owner_type text,owner_id numeric,channel text,priority text,title_ru text,body_ru text,title_en text,body_en text,action_type text,action_url text,payload_json jsonb,status text,scheduled_at timestamptz,sent_at timestamptz,expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.notification_deliveries(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,notification_id bigint REFERENCES public.app_notifications(id),delivery_uid text UNIQUE,channel text,provider text,target text,status text,attempt_count integer,last_error text,sent_at timestamptz,delivered_at timestamptz,failed_at timestamptz,created_at timestamptz,updated_at timestamptz);
